  ('8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$परशुराम ने 'उलटउँ महि जहँ लहि तवव राजू' कहकर जनक को कितनी बड़ी धमकी दी थी? इसका क्या प्रभाव पड़ा होगा?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
