INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('d6648398-a99a-44af-9806-e10b23bf46e6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोस्वामी तुलसीदास का जन्म आज के उत्तर प्रदेश में हुआ था। इनका जीवन-काल 16वीं–17वीं शताब्दी (सन् 1532–1623) के मध्य माना गया है। रामचरितमानस तुलसीदास का प्रसिद्ध महाकाव्य है। रामचरितमानस उनकी अनन््य राामभक्‍तति और उनके सृजनाात्मक कौशल काा मनोरम उदााहरण है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b5e5fd42-1df1-4b3e-90e8-8ee2a4e076f2', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी अन््य प्रमुख रचनााएँ कवितावली, गीतावली, दोहावली, कृष््णगीतावली, विनयपत्रिका, हनुमान बाहुक हैं। तुलसीदाास की रचनााओं में रााम माानववीयय मर््ययादााओं और आदशशों के प्रतीक हैं जिनके मााध््यम से उन्होंने नीति, स्नेह, शील, विनयय, त््ययााग जैसे मूल््यों को प्रतिष्‍ठ‍ित कियाा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('100347e7-70aa-4364-a26a-000aed9ae4cd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माानवव-प्रकृति, लोकजीववन और जीववन-जगत संबंधी गहरी अंतर्दृष्‍ट‍ि उनके कााव््य में दिखााई पड़ती है। तुलसीदाास संस्कृत के श्रेष्‍ठ ज्ञााताा थे। उनकाा अववधी और ब्रज दोनों भााषााओं पर समाान अधिकाार थाा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0fb24f61-2615-4c06-a305-afe58d38291b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्होंने रामचरितमानस की रचना अवधी में और विनयपत्रिका तथाा कवितावली की रचनाा ब्रजभााषाा में की। कााशी में उनकाा देहाववसाान हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a500998f-415e-44f5-ab14-6f37baf9519d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रस्तुत अंश ‘रामचरितमानस’ के ‘बालकांड’ से लिया गया है। सीता स्‍वयंवर में श्ीराम द्ारा शिव-धनुष भंग का समाचार जब मुन‍‍ि परशुराम को मिलता है तो वे आक्रोशित होकर वहाँ आते हैं। शिव-धनुष को खंडित देखकर वे तीव्र रोष प्रकट करते हैं और सभा में उपस््थित सभी राजाओं पर क्रोधित होते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ba0e2692-c7e1-4a02-920a-4c72909f1745', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ तुलसीदास ने परशुराम के रोषपूर््ण और तेजस््ववी रूप का वर््णन किया है। प्रस्तुत अंश में, सभा में उपस््थित राजाओं के भय, विश््‍ववामित्र और जनक की सभा में उपस््थिति, जनक द्ारा सीता-स््वयंवर के बारे में बताने, विश््‍ववामित्र द्ारा राम-लक्षष्मणण का परशुराम से परिचय एवं सम्मानपूर््वक अभिवादन के बाद कथा आगे बढ़ती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
