  ('23e391a9-0887-48e9-a5b9-351ec84578e0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सो बिलगााउ बिहााइ समााजाा। न त माारे जैहहिं सब रााजाा॥ सुनि मुनि बचन लखन मुसुकााने। बोले परसुधरहि अपमााने॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e8bf71c2-f72d-4dd1-bc08-96276903009a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मन पछिताति सीयय महताारी। बिधि अब सँववरी बाात बिगाारी॥ भृगुपति कर सुभााउ सुनि सीताा। अरध निमेष कलप सम बीताा॥$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4fa35c98-e5d7-4734-baae-61abe49dd16c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोस्वामी तुलसीदास का जन्म आज के उत्तर प्रदेश में हुआ था। इनका जीवन-काल 16वीं–17वीं शताब्दी (सन् 1532–1623) के मध्य माना गया है। रामचरितमानस तुलसीदास का प्रसिद्ध महाकाव्य है। रामचरितमानस उनकी अनन््य राामभक्‍तति और उनके सृजनाात्मक कौशल काा मनोरम उदााहरण है। उनकी अन््य प्रमुख रचनााएँ कवितावली, गीतावली, दोहावली, कृष््णगीतावली, विनयपत्रिका, हनुमान बाहुक हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ecbbb01c-f9a2-4fc9-98cb-edc076f35ba3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुलसीदाास की रचनााओं में रााम माानववीयय मर््ययादााओं और आदशशों के प्रतीक हैं जिनके मााध््यम से उन्होंने नीति, स्नेह, शील, विनयय, त््ययााग जैसे मूल््यों को प्रतिष्‍ठ‍ित कियाा है। माानवव-प्रकृति, लोकजीववन और जीववन-जगत संबंधी गहरी अंतर्दृष्‍ट‍ि उनके कााव््य में दिखााई पड़ती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d29f9ed9-bdef-4f5c-90ee-4afa585bd5e4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुलसीदाास संस्कृत के श्रेष्‍ठ ज्ञााताा थे। उनकाा अववधी और ब्रज दोनों भााषााओं पर समाान अधिकाार थाा। उन्होंने रामचरितमानस की रचनाा अववधी में और विनयपत्रिका तथाा कवितावली की रचनाा ब्रजभााषाा में की। कााशी में उनकाा देहाववसाान हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('768431d8-e776-4a7b-a7c1-73ace66e9909', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रस्तुत अंश ‘रामचरितमानस’ के ‘बालकांड’ से लिया गया है। सीता स्‍वयंवर में श्ीराम द्ारा शिव-धनुष भंग का समाचार जब मुन‍‍ि परशुराम को मिलता है तो वे आक्रोशित होकर वहाँ आते हैं। शिव-धनुष को खंडित देखकर वे तीव्र रोष प्रकट करते हैं और सभा में उपस््थित सभी राजाओं पर क्रोधित होते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4a63ae80-d4d2-40bc-a6ec-c5bf9fbf9941', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ तुलसीदास ने परशुराम के रोषपूर््ण और तेजस््ववी रूप का वर््णन किया है। प्रस्तुत अंश में, सभा में उपस््थित राजाओं के भय, विश््‍ववामित्र और जनक की सभा में उपस््थिति, जनक द्ारा सीता-स््वयंवर के बारे में बताने, विश््‍ववामित्र द्ारा राम-लक्षष्मणण का परशुराम से परिचय एवं सम्मानपूर््वक अभिवादन के बाद कथा आगे बढ़ती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
