  ('37751df9-2895-47f4-be3a-338428f14033', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रस्तुत अंश में, सभा में उपस््थित राजाओं के भय, विश््‍ववामित्र और जनक की सभा में उपस््थिति, जनक द्ारा सीता-स््वयंवर के बारे में बताने, विश््‍ववामित्र द्ारा राम-लक्षष्मणण का परशुराम से परिचय एवं सम्मानपूर््वक अभिवादन के बाद कथा आगे बढ़ती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f4b8d6e5-4bf4-4f05-9b39-304a3d32847f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोस्वामी तुलसीदास का जन्म आज के उत्तर प्रदेश में हुआ था। इनका जीवन-काल 16वीं–17वीं शताब्दी (सन् 1532–1623) के मध््य माानाा गयाा है। रामचरितमानस तुलसीदाास काा प्रसिद्ध महााकााव्‍यय है। रामचरितमानस उनकी अनन््य राामभक्‍तति और उनके सृजनाात्मक कौशल काा मनोरम उदााहरण है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f41dd2f7-0240-4c0b-89fe-37ecbe2ba4d4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुलसीदाास की रचनााओं में रााम माानववीयय मर््ययादााओं और आदशशों के प्रतीक हैं जिनके मााध््यम से उन्होंने नीति, स्नेह, शील, विनयय, त््ययााग जैसे मूल््यों को प्रतिष्‍ठ‍ित कियाा है। माानवव-प्रकृति, लोकजीववन और जीववन-जगत संबंधी गहरी अंतर्दृष्‍ट‍ि उनके कााव््य में दिखााई पड़ती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a9c504af-e89d-4db0-8b5b-bc06d470b264', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुलसीदाास संस्कृत के श्रेष्‍ठ ज्ञााताा थे। उनकाा अववधी और ब्रज दोनों भााषााओं पर समाान अधिकाार थाा। उन्होंने रामचरितमानस की रचनाा अववधी में और विनयपत्रिका तथाा कवितावली की रचनाा ब्रजभााषाा में की। कााशी में उनकाा देहाववसाान हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d814b139-19b4-43ed-8769-0c2b3458f563', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रस्तुत अंश ‘रामचरितमानस’ के ‘बालकांड’ से लिया गया है। सीता स्‍वयंवर में श्ीराम द्ारा शिव-धनुष भंग का समाचार जब मुन‍‍ि परशुराम को मिलता है तो वे आक्रोशित होकर वहाँ आते हैं। शिव-धनुष को खंडित देखकर वे तीव्र रोष प्रकट करते हैं और सभा में उपस््थित सभी राजाओं पर क्रोधित होते हैं। यहाँ तुलसीदास ने परशुराम के रोषपूर््ण और तेजस््ववी रूप का वर््णन किया है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('675f7bf4-75f9-4d81-89d0-8e3d615585c8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$देखत भृगुपति बेषु कराालाा। उठे सकल भयय बिकल भुआलाा॥ पितु समेत कहि कहि निज नाामाा। लगे करन सब दंड प्रनाामाा॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('f414d731-f0cb-41af-8f27-ea6030d51114', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जेहि सुभाययँ चितवहिं हितु जाानी। सो जाानइ जनु आइ खुटाानी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5afa13bf-e0ff-47cb-8c4c-b0270fcb23e4', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जनक बहोरि आइ सिरु नावावा। सीयय बोलााइ प्रनाामु करावावा॥ आसिष दीन््हहि सखीं हरषानीीं। निज समााज लै गइ« सयानीीं॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
