  ('c1dc5fa1-df1f-4101-aa2d-c3e17d11be18', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$देखत भृगुपति बेषु कराालाा। उठे सकल भयय बिकल भुआलाा॥ पितु समेत कहि कहि निज नाामाा। लगे करन सब दंड प्रनाामाा॥ जेहि सुभाययँ चितवहिं हितु जाानी। सो जाानइ जनु आइ खुटाानी॥ जनक बहोरि आइ सिरु नावावा। सीयय बोलााइ प्रनाामु करावावा॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6da980c6-21e3-408c-805e-403b8bcbd540', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$समााचाार कहि जनक सुनााए। जेहि काारन महीप सब आए॥ सुनत बचन फिरि अनत निहाारे। देखे चाापखंड महि डाारे॥ अति रिस बोले बचन कठोराा। कहु जड़ जनक धनुष कै तोराा॥ बेगि देखााउ मूढ़ न त आजू। उलटउँ महि जहँ लहि तवव रााजू॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('dbcf81a5-d91a-48e6-9f42-3d86fe724e6a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अति डरु उतरु देत नृपु नाहीीं।कुटििल भूप हरषे मन माहीीं॥ सुर मुनि नााग नगर नर नाारी। सोचहिं सकल त्राास उर भाारी॥ मन पछिताति सीयय महताारी। बिधि अब सँववरी बाात बिगाारी॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('6d7d88a5-00ad-4cde-b7c4-5f85f7a780e6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भृगुपति कर सुभााउ सुनि सीताा। अरध निमेष कलप सम बीताा॥ सभयय बिलोके लोग सब जानि जाानकी भीरु। हृदययँ न हरषु बिषाादु कछु बोले श्ीरघुबीरु॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('595b8709-ccbd-4a14-94ab-b773a3565cf7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नााथ संभुधनु भंजनिहााराा। होइहि केउ एक दाास तुम््हहााराा॥ आययसु कााह कहिअ किन मोही। सुनि रिसााइ बोले मुनि कोही॥ सेववकु सो जो करै सेववकााई। अरि करनी करि करिअ लरााई॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4f26b20c-f7e0-4ba7-a1f6-d37babfcccab', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुनहु रााम जेहिं सिववधनु तोराा। सहसबााहु सम सो रिपु मोराा॥ सो बिलगााउ बिहााइ समााजाा। न त माारे जैहहिं सब रााजाा॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a3c191bf-5159-4dcb-adf9-0d9c2f0411fd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सुनि मुनि बचन लखन मुसुकााने। बोले परसुधरहि अपमााने॥ बहु धनुहीं तोरीं लरिकााइ«। कबहुँ न असि रिस कीन््हहि गोसााइ«॥ एहि धनु पर ममताा केहि हेतू। सुनि रिसााइ कह भृगुकुलकेतू॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('73fa4bcc-d257-4e43-b831-5b849d64d660', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '3fd9ffa8-6a3e-43e7-9fe8-3712ccfdea79', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रे नृप बाालक कााल बस बोलत तोहि न सँभाार। धनुही सम तिपुराारि धनु बिदित सकल संसाार॥$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-39-871Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
